import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
TOKEN = os.getenv("API_TOKEN")
PATIENT_ID = os.getenv("PATIENT_ID", "patient-id")
PROVIDER_ID = os.getenv("PROVIDER_ID", "provider-id")
TEST_RESULT_ID = os.getenv("TEST_RESULT_ID", "test-result-id")
INVENTORY_ITEM_ID = os.getenv("INVENTORY_ITEM_ID", "inventory-item-id")
OUTDATED_APPOINTMENT_IDS = [
    value.strip()
    for value in os.getenv("OUTDATED_APPOINTMENT_IDS", "").split(",")
    if value.strip()
]

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if TOKEN:
    session.headers["Authorization"] = f"Bearer {TOKEN}"


def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return None


# Review the provider's schedule and historical reports for outcome patterns.
provider_schedule = request("GET", f"/providers/{PROVIDER_ID}/schedule")
historical_reports = request("GET", "/reports/history")

# Update the patient's health record with clinical notes and test results.
record_update = request(
    "POST",
    f"/patients/{PATIENT_ID}/records/update",
    json={
        "clinical_notes": os.getenv("CLINICAL_NOTES", ""),
        "test_results": [],
    },
)

# Confirm the test result is available, then retrieve its details for analysis.
available_test_results = request("GET", "/test-results/available")
available_ids = set()

if isinstance(available_test_results, list):
    available_ids = {
        str(item.get("id"))
        for item in available_test_results
        if isinstance(item, dict) and item.get("id") is not None
    }
elif isinstance(available_test_results, dict):
    results = available_test_results.get("results", [])
    if isinstance(results, list):
        available_ids = {
            str(item.get("id"))
            for item in results
            if isinstance(item, dict) and item.get("id") is not None
        }

test_result_details = None
if TEST_RESULT_ID in available_ids:
    test_result_details = request("GET", f"/test-results/{TEST_RESULT_ID}")

# Inspect inventory levels. The documented API does not provide an item-specific
# inventory endpoint or an inventory deletion endpoint.
inventory = request("GET", "/inventory")
inventory_item = None
items = inventory if isinstance(inventory, list) else inventory.get("items", [])
if isinstance(items, list):
    inventory_item = next(
        (
            item
            for item in items
            if isinstance(item, dict)
            and str(item.get("id", item.get("item_id", ""))) == INVENTORY_ITEM_ID
        ),
        None,
    )

# Remove outdated appointments using the documented appointment update endpoint.
# No appointment deletion endpoint is documented, so mark them as cancelled.
cancelled_appointments = []
for appointment_id in OUTDATED_APPOINTMENT_IDS:
    cancelled_appointments.append(
        request(
            "PUT",
            f"/appointments/{appointment_id}",
            json={"status": "cancelled"},
        )
    )

