import requests

BASE_URL = "https://api.socbench.example"

# Retrieve future generation projections and keep renewable sources.
projections_response = requests.get(
    f"{BASE_URL}/analytics/projections",
    timeout=30,
)
projections_response.raise_for_status()
projections_data = projections_response.json()

renewable_types = {"solar", "wind", "hydro"}
renewable_projections = [
    projection
    for projection in projections_data.get("projections", [])
    if projection.get("resourceType", "").lower() in renewable_types
]

# Retrieve the user's dashboard summary, including total usage and alerts.
user_id = "12345"
dashboard_response = requests.get(
    f"{BASE_URL}/dashboard/summary",
    params={"userId": user_id},
    timeout=30,
)
dashboard_response.raise_for_status()
dashboard = dashboard_response.json()

# Schedule maintenance for the specified pipeline facility.
maintenance_payload = {
    "facilityId": "pipeline-001",
    "maintenanceDate": "2026-11-15T09:00:00Z",
    "details": "Schedule pipeline maintenance to optimize operational performance.",
}
maintenance_response = requests.post(
    f"{BASE_URL}/maintenance/scheduling",
    json=maintenance_payload,
    timeout=30,
)
maintenance_response.raise_for_status()

result = {
    "renewableProjections": renewable_projections,
    "dashboard": {
        "totalUsage": dashboard.get("totalUsage"),
        "alerts": dashboard.get("alerts", []),
    },
    "maintenance": maintenance_response.json() if maintenance_response.content else {
        "status_code": maintenance_response.status_code
    },
}

