    f"{BASE_URL}/reports/custom",
    json={
        "title": f"Ownership history and inquiry insights for {property_id}",
        "criteria": {
            "property_id": property_id,
            "ownership_history": ownership_history,
            "inquiry_response": inquiry_result,
        },
        "insights": [
            "Detailed ownership history",
            "Clarifications and additional information from the inquiry",
        ],
    },
)
